--liquibase formatted sql

--changeset trellis:course-001-course
--comment: Course aggregate (generated by new-module.sh). code is the public id; version is the optimistic
--comment: lock and the ETag. No foreign keys between modules: a module owns its tables (decision T10).
CREATE SEQUENCE course_id_seq INCREMENT BY 1;
CREATE TABLE course (
    id           BIGINT DEFAULT nextval('course_id_seq')          PRIMARY KEY,
    code         VARCHAR(17)   NOT NULL,
    name         VARCHAR(200)  NOT NULL,
    description  TEXT          NOT NULL,
    status       VARCHAR(16)   NOT NULL,
    owner_id     VARCHAR(200)  NOT NULL,
    version      BIGINT        NOT NULL,
    created_at   TIMESTAMPTZ   NOT NULL,
    updated_at   TIMESTAMPTZ   NOT NULL,
    activated_at TIMESTAMPTZ,
    archived_at  TIMESTAMPTZ,
    CONSTRAINT uq_course_code UNIQUE (code),
    CONSTRAINT ck_course_status CHECK (status IN ('DRAFT', 'ACTIVE', 'ARCHIVED')),
    CONSTRAINT ck_course_version CHECK (version >= 1)
);
-- Keyset order of the list API: (created_at DESC, id DESC).
CREATE INDEX ix_course_created ON course (created_at DESC, id DESC);
--rollback DROP TABLE course; DROP SEQUENCE course_id_seq;
